import os,json,hashlib,time
from pathlib import Path
names=set(["P2OriginalFiniteTentBankSelectorMargins.lean","P5ActualFourNativeBoxFullNorm.lean","P5AllRankCauchyKernelIntegral.lean","P5AllRankMixedFourierPointwise.lean","P5AllWordAmbientOccurrenceBound.lean","P5OriginalFourSelectedSmoothWBindingGap.lean","P5OriginalOneLongActualChartE5.lean","P5OriginalOneLongMertensChartHarmonic.lean","P5PositiveFourProfileLocalZeroSmooth.lean"])
