errors=[]; hits=[]; counts={}; number_dirs=number_files=0
def err(e): errors.append({'path':str(e.filename),'error':str(e)})
for directory, dirs, files in os.walk(root,topdown=True,followlinks=False,onerror=err):
    number_dirs+=1
    number_files+=len(files)
    keep=[]
    for d in dirs:
        skip=d in ('.git','node_modules') or (os.path.basename(directory)=='.lake' and d in ('build','packages'))
        if skip:
            label=('.lake/'+d) if os.path.basename(directory)=='.lake' and d in ('build','packages') else d
            counts[label]=counts.get(label,0)+1
        else: keep.append(d)
    dirs[:]=sorted(keep)
    for name in sorted(names.intersection(files)):
        path=Path(directory)/name
        try:
            h=hashlib.sha256(); n=0
            with path.open('rb') as f:
                while block:=f.read(65536):
                    h.update(block); n+=len(block)
            hits.append({'name':name,'path':str(path),'bytes':n,'sha256':h.hexdigest(),'is_symlink':path.is_symlink()})
        except OSError as e: err(e)
print(json.dumps({'root':root,'exact_basenames':sorted(names),'directory_symlinks_followed':False,'prune':['**/.git','**/node_modules','**/.lake/build','**/.lake/packages'],'pruned_directory_counts':counts,'visited_directories':number_dirs,'encountered_files':number_files,'elapsed_seconds':time.monotonic()-start,'hits':hits,'errors':errors},sort_keys=True))
